tool_and_message_events.command:
/bin/bash -lc "node --help | rg 'strip-types|require-module'
node --input-type=commonjs -e '
(async () => {
  console.log(\"require.resolve:\", require.resolve(\"#codec\"));
  try { require(\"#codec\"); } catch (error) { console.log(\"require:\", error.code); }
  const codec = await import(\"#codec\");
  console.log(\"import:\", codec.report(5));
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});'
node --input-type=module -e '
import {spawnSync} from \"node:child_process\";
for (const args of [[\"start\", \"--\", \"5\"], [\"run\", \"drain\"]]) {
  const result = spawnSync(\"npm\", [\"--silent\", ...args], {encoding: \"utf8\", timeout: 5000});
  console.log(JSON.stringify({args, stdout: result.stdout, stderr: result.stderr, exit: result.status, signal: result.signal, error: result.error?.message}));
  if (result.error) process.exitCode = 1;
}'"

